window.SOCIALMATE_PUBLIC_PLACES = {"meta":{"kind":"hainan-public-read-only","count":115,"source":"Hainan-Travel-Guide baseline places.json"},"places":[{"id":1,"name":"龙兴路","enName":"Longxing Road","city":"海口","category":"城市街拍","cn":"海口市龙华区国贸片区的龙兴路。这条不到500米的小街最近成了很火的街拍地，很多博主和年轻帅哥美女专程来拍照。咖啡馆的门头、绿植、外摆桌椅和复古小店都很上镜，下午光线好，随便走走就容易出片。","en":"Longxing Road is in the Guomao area of Longhua District, Haikou. This short street has become one of Haikou's favorite photo spots. Influencers and stylish young locals come for the pretty storefronts, outdoor cafés, and vintage shops. It's especially photogenic in the afternoon.","location":"海口市龙华区国贸片区的龙兴路","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%BE%99%E5%85%B4%E8%B7%AF","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%BE%99%E5%85%B4%E8%B7%AF"},{"id":2,"name":"滨海新村","enName":"Binhai Xincun Neighborhood","city":"海口","category":"城市街拍","cn":"海口市龙华区滨海大道附近的滨海新村老社区。这里的魅力不是大景区，而是老居民楼之间冒出来的小众咖啡馆和有趣店面。旧墙、窄巷和新潮门头放在一起，很适合拍一点自然的生活感照片。","en":"You can find it at Binhai Xincun, an older neighborhood near Binhai Avenue in Haikou's Longhua District. The contrast is what makes it fun: old apartment blocks, narrow alleys, and trendy little cafés next door. It feels more like discovering a local neighborhood than visiting a tourist attraction.","location":"海口市龙华区滨海大道附近的滨海新村老社区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%BB%A8%E6%B5%B7%E6%96%B0%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%BB%A8%E6%B5%B7%E6%96%B0%E6%9D%91"},{"id":3,"name":"骑楼老街","enName":"Qilou Old Street","city":"海口","category":"城市街拍","cn":"海口市龙华区中山路一带，靠近海口钟楼。最值得看的是两侧一整排带骑楼走廊的南洋老房子，和东南亚不少城市的老街有点像。白天适合拍建筑，边走边尝海南粉、清补凉和传统点心。","en":"You can find it at Zhongshan Road in Longhua District, near Haikou Clock Tower. The long rows of arcaded buildings have a Southeast Asian feel you don't see everywhere in China. Look up at the old balconies, take street photos, and stop for Hainanese noodles or a sweet local dessert.","location":"海口市龙华区中山路一带，靠近海口钟楼","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%AA%91%E6%A5%BC%E8%80%81%E8%A1%97","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%AA%91%E6%A5%BC%E8%80%81%E8%A1%97"},{"id":4,"name":"云洞图书馆","enName":"Cloud Cave Library","city":"海口","category":"城市街拍","cn":"海口市龙华区世纪广场路1号，海口湾海边。海边这栋弯弯曲曲的白色建筑就像雕塑，弧线门洞和大海放在同一张照片里特别漂亮。很多人傍晚来拍日落，想进馆阅读则要查看预约安排。","en":"It is at No. 1 Century Square Road in Longhua District, right beside Haikou Bay. The white curved building looks almost like a sculpture beside the water. Its openings frame the sea beautifully, and sunset is a popular time for photos. Check the booking rules if you want to go inside.","location":"海口市龙华区世纪广场路1号，海口湾海边","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%BA%91%E6%B4%9E%E5%9B%BE%E4%B9%A6%E9%A6%86","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%BA%91%E6%B4%9E%E5%9B%BE%E4%B9%A6%E9%A6%86"},{"id":5,"name":"天空之山","enName":"Sky Mountain","city":"海口","category":"城市街拍","cn":"海口市美兰区美丽沙路附近、海甸五西路海岸。它不像普通的观海平台，更像一条能走上屋顶的白色海边艺术建筑。沿着弯曲步道慢慢走，能从不同角度拍海和建筑，顺便在附近喝咖啡。","en":"It is near Meilisha Road and Haidian Fifth West Road in Haikou's Meilan District. This isn't a typical seaside lookout. You can follow the curved walkway over an unusual white building, finding different angles for the sea and architecture, then grab a coffee nearby.","location":"海口市美兰区美丽沙路附近、海甸五西路海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%A4%A9%E7%A9%BA%E4%B9%8B%E5%B1%B1","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%A4%A9%E7%A9%BA%E4%B9%8B%E5%B1%B1"},{"id":6,"name":"海大南门夜市","enName":"Hainan University South Gate Night Market","city":"海口","category":"城市街拍","cn":"海口市美兰区海甸三西路14号，海南大学南门外。它是一条晚上才真正热闹起来的小吃街，几百米路边能看到密密麻麻的摊位。建议空着肚子来，海南粉、烧烤、清补凉和各地小吃可以一路尝。","en":"It is outside Hainan University's south gate, No. 14 Haidian Third West Road, Meilan District. This street really comes alive after dark, with food stalls packed along the road. Come hungry and try Hainanese noodles, barbecue, chilled coconut desserts, and whatever else catches your eye.","location":"海口市美兰区海甸三西路14号，海南大学南门外","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%A4%A7%E5%8D%97%E9%97%A8%E5%A4%9C%E5%B8%82","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%A4%A7%E5%8D%97%E9%97%A8%E5%A4%9C%E5%B8%82"},{"id":7,"name":"荣山寮村","enName":"Rongshanliao Village","city":"海口","category":"城市街拍","cn":"海口市秀英区西秀镇荣山寮村，西海岸一带。这里原本是渔村，现在除了渔船，还能看到沙滩鱼市和越来越多的海边休闲小店。傍晚一边看日落一边逛渔获市场，氛围比普通海滩更有生活味。","en":"You can find it at Rongshanliao Village in Xixiu Town, Xiuying District, on Haikou's west coast. This is still a working fishing village, with boats and a beachside fish market alongside newer hangout spots. Come toward sunset to see the local catch and enjoy the warm evening light.","location":"海口市秀英区西秀镇荣山寮村，西海岸一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%8D%A3%E5%B1%B1%E5%AF%AE%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%8D%A3%E5%B1%B1%E5%AF%AE%E6%9D%91"},{"id":8,"name":"898艺术村","enName":"898 Art Village","city":"海口","category":"城市街拍","cn":"海口市美兰区灵山镇美庄村，靠近江东新区白驹大道。村里的老房子被画上了彩色墙绘，还聚集着画室、陶艺和黎锦等手作活动。不是千篇一律的商业街，更像走进一个有人创作、有人生活的艺术小村。","en":"You can find it at Meizhuang Village in Lingshan Town, Meilan District, near Baiju Avenue. Colorful murals cover old village walls, and artists work with painting, pottery, and local textiles here. It feels like a working creative village rather than a polished shopping street.","location":"海口市美兰区灵山镇美庄村，靠近江东新区白驹大道","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3898%E8%89%BA%E6%9C%AF%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3898%E8%89%BA%E6%9C%AF%E6%9D%91"},{"id":9,"name":"雷琼火山口地质公园","enName":"Haikou Volcano Park","city":"海口","category":"城市街拍","cn":"海口市秀英区石山镇，靠近火山口公园景区入口。海口不只有海滩，城市西边还有古老的火山群。可以沿着山路走到火山口，看看黑色火山岩和长满植物的火山地形，和海南海边风景完全不同。","en":"You can find it at Shishan Town in Xiuying District, at the Haikou volcano scenic area. Haikou isn't only about beaches—it also has ancient volcanic landscapes. Walk toward the crater, see the dark rock, and enjoy a very different side of the island.","location":"海口市秀英区石山镇，靠近火山口公园景区入口","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%9B%B7%E7%90%BC%E7%81%AB%E5%B1%B1%E5%8F%A3%E5%9C%B0%E8%B4%A8%E5%85%AC%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%9B%B7%E7%90%BC%E7%81%AB%E5%B1%B1%E5%8F%A3%E5%9C%B0%E8%B4%A8%E5%85%AC%E5%9B%AD"},{"id":10,"name":"北港岛","enName":"Beigang Island","city":"海口","category":"城市街拍","cn":"海口市美兰区演丰镇北港岛，东寨港海岸附近。岛上保留着渔船和渔村生活，退潮时大片滩涂会露出来。可以在安全区域观察小螃蟹、贝类和赶海的人，但一定要看潮汐，不要往深滩走。","en":"You can find it at Beigang Island in Yanfeng Town, Meilan District, close to Dongzhai Harbor. This quiet fishing island is especially interesting at low tide, when wide mudflats appear. You might see small crabs, shells, and locals collecting seafood. Always check the tides and stay in safe areas.","location":"海口市美兰区演丰镇北港岛，东寨港海岸附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%8C%97%E6%B8%AF%E5%B2%9B","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%8C%97%E6%B8%AF%E5%B2%9B"},{"id":11,"name":"海甸溪畔","enName":"Haidian Creek Waterfront","city":"海口","category":"城市街拍","cn":"海口市美兰区海甸溪沿岸，东坡老码头附近。这片河畔最舒服的时段是天快黑的时候，水面倒映着灯光，附近有不少临水吃喝的地方。它的乐趣是坐在外摆座位上慢慢聊天，看两岸城市亮起来。","en":"It is along Haidian Creek in Meilan District, near Dongpo Old Wharf. Come around dusk, when the lights begin reflecting on the creek. The waterfront cafés and restaurants are great for sitting outside and watching the city change from day to night.","location":"海口市美兰区海甸溪沿岸，东坡老码头附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E7%94%B8%E6%BA%AA%E7%95%94","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E7%94%B8%E6%BA%AA%E7%95%94"},{"id":12,"name":"海甸岛捕捞村","enName":"Haidian Fishing Village","city":"海口","category":"城市街拍","cn":"海口市美兰区海甸岛捕捞村，靠近海南大学南门和东坡老码头。老渔村里还留着晒鱼干、卖鱼货的生活场景，转个弯又可能遇到咖啡馆、甜品店或服装小店。老渔村和年轻人的新潮生活混在一起，就是这里最特别的地方。","en":"You can find it at Bulao Village on Haidian Island, near Hainan University and Dongpo Old Wharf. You may see fish being dried or sold in one lane, then find a stylish café around the corner. This mix of a working fishing village and young creative businesses is what makes the area special.","location":"海口市美兰区海甸岛捕捞村，靠近海南大学南门和东坡老码头","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E7%94%B8%E5%B2%9B%E6%8D%95%E6%8D%9E%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E7%94%B8%E5%B2%9B%E6%8D%95%E6%8D%9E%E6%9D%91"},{"id":13,"name":"侨中里文化街","enName":"Qiaozhongli Cultural Street","city":"海口","category":"城市街拍","cn":"海口市龙华区海秀中路92号，海南华侨中学对面。这里的店铺和街景有不少集装箱、动漫元素，学生和年轻人比较多。适合随便逛逛、吃点甜品、看看小店，不是需要买门票的大景区。","en":"It is at No. 92 Haixiu Middle Road, Longhua District, opposite Hainan Overseas Chinese Middle School. This small street uses shipping-container designs and anime-style details. It's a casual student hangout with snacks and little shops, not a major sightseeing attraction.","location":"海口市龙华区海秀中路92号，海南华侨中学对面","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%BE%A8%E4%B8%AD%E9%87%8C%E6%96%87%E5%8C%96%E8%A1%97","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%BE%A8%E4%B8%AD%E9%87%8C%E6%96%87%E5%8C%96%E8%A1%97"},{"id":14,"name":"高兴里特色文化街区","enName":"Gaoxingli Creative District","city":"海口","category":"城市街拍","cn":"海口市琼山区高登西街一带。这是偏年轻潮流路线的开放式商业街区，除了吃饭，还有设计感店铺和展览空间。和普通封闭商场不同，它更适合边走边拍，碰到市集或活动时会更好玩。","en":"It is around Gaodeng West Street in Qiongshan District, Haikou. This open-air shopping area mixes restaurants, creative stores, and occasional art events. It's more fun to wander through than a standard indoor mall, especially when a market or exhibition is happening.","location":"海口市琼山区高登西街一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%AB%98%E5%85%B4%E9%87%8C%E7%89%B9%E8%89%B2%E6%96%87%E5%8C%96%E8%A1%97%E5%8C%BA","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%AB%98%E5%85%B4%E9%87%8C%E7%89%B9%E8%89%B2%E6%96%87%E5%8C%96%E8%A1%97%E5%8C%BA"},{"id":15,"name":"FUNBAY自在湾街区","enName":"FUNBAY Waterfront","city":"海口","category":"城市街拍","cn":"海口市龙华区观海路一带，万绿园附近。这片靠海的街区把餐饮、海风和夜间音乐放在一起，比较适合晚餐后继续逛。想感受海口年轻人的周末夜生活，可以留意现场演出和主题活动。","en":"It is on Guanhai Road in Longhua District, near Evergreen Park. This waterfront hangout combines food, sea breezes, and live music on some evenings. It's a good place to spend time after dinner, especially when there's a weekend event.","location":"海口市龙华区观海路一带，万绿园附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3FUNBAY%E8%87%AA%E5%9C%A8%E6%B9%BE%E8%A1%97%E5%8C%BA","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3FUNBAY%E8%87%AA%E5%9C%A8%E6%B9%BE%E8%A1%97%E5%8C%BA"},{"id":16,"name":"西溪里商业街","enName":"Xixili Riverside Street","city":"海口","category":"城市街拍","cn":"海口市美兰区海达路与海甸一东路交叉口以东，海甸溪北岸。这条商业街沿海甸溪北岸铺开，有临水餐厅和小酒馆，晚上的微醺氛围比白天更突出。坐在户外看水面和对岸老城区的灯光，是这里真正吸引人的地方。","en":"It is near the crossing of Haida Road and Haidian First East Road, on the north bank of Haidian Creek in Meilan District. This riverside street has restaurants and small bars facing Haidian Creek. Come in the evening for the relaxed drinks scene and views of the lights across the water.","location":"海口市美兰区海达路与海甸一东路交叉口以东，海甸溪北岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%A5%BF%E6%BA%AA%E9%87%8C%E5%95%86%E4%B8%9A%E8%A1%97","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%A5%BF%E6%BA%AA%E9%87%8C%E5%95%86%E4%B8%9A%E8%A1%97"},{"id":17,"name":"华彩海口湾滨海街区","enName":"Huacai Haikou Bay Waterfront","city":"海口","category":"城市街拍","cn":"海口市美兰区海甸岛北侧，华彩海口湾商圈。这里更适合喜欢现代城市海景的人：一边是商场和餐厅，一边能看海岸和城市灯光。傍晚来吃饭，饭后沿海边走走，比正午晒太阳舒服。","en":"You can find it at Huacai Haikou Bay on the north side of Haidian Island, Meilan District. Here you get a modern seaside city view, with restaurants and shopping close to the coast. Evening is the best time to eat, take a walk, and see the lights along the bay.","location":"海口市美兰区海甸岛北侧，华彩海口湾商圈","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%8D%8E%E5%BD%A9%E6%B5%B7%E5%8F%A3%E6%B9%BE%E6%BB%A8%E6%B5%B7%E8%A1%97%E5%8C%BA","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%8D%8E%E5%BD%A9%E6%B5%B7%E5%8F%A3%E6%B9%BE%E6%BB%A8%E6%B5%B7%E8%A1%97%E5%8C%BA"},{"id":18,"name":"水巷口","enName":"Shuixiangkou Food Street","city":"海口","category":"城市街拍","cn":"海口市龙华区骑楼老街水巷口一带。水巷口最出名的不是建筑，而是吃的。早上可以尝一碗辣汤饭，下午找老盐饮料、海南小吃，特别适合带朋友体验真正的海口味道。","en":"You can find it at Shuixiangkou, beside Qilou Old Street in Longhua District. Come here for food as much as for the old streets. Try spicy breakfast rice soup, local snacks, or a salty fruit drink—the flavors are very Haikou.","location":"海口市龙华区骑楼老街水巷口一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B0%B4%E5%B7%B7%E5%8F%A3","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B0%B4%E5%B7%B7%E5%8F%A3"},{"id":19,"name":"得胜沙路","enName":"Deshengsha Road","city":"海口","category":"城市街拍","cn":"海口市龙华区得胜沙路，钟楼与骑楼街区附近。这条街保留着老骑楼商贸街的感觉，店招、楼上窗户和老式门面都很有年代感。适合和骑楼老街连着逛，找一些不那么标准游客照的街景。","en":"You can find it at Deshengsha Road in Longhua District, near Clock Tower and Qilou Old Street. The signs, balconies, and old shopfronts show another side of Haikou's trading history. Walk it together with Qilou Old Street for more interesting street photos.","location":"海口市龙华区得胜沙路，钟楼与骑楼街区附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%BE%97%E8%83%9C%E6%B2%99%E8%B7%AF","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%BE%97%E8%83%9C%E6%B2%99%E8%B7%AF"},{"id":20,"name":"府城老街","enName":"Fucheng Old Streets","city":"海口","category":"城市街拍","cn":"海口市琼山区府城片区，忠介路和府城老街附近。这里是本地人熟悉的老城区，街巷里藏着很多小吃店和老摊位。想吃地道的海南粉、传统甜品，或者看看下班后的老城生活，可以来这里走走。","en":"You can find it at The Fucheng area of Qiongshan District, around Zhongjie Road. This old town area is full of everyday local life and small food shops. It's a good place for Hainanese noodles, traditional sweets, and an unhurried walk through older streets.","location":"海口市琼山区府城片区，忠介路和府城老街附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%BA%9C%E5%9F%8E%E8%80%81%E8%A1%97","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%BA%9C%E5%9F%8E%E8%80%81%E8%A1%97"},{"id":21,"name":"长堤路滨水街区","enName":"Changdi Road Waterfront","city":"海口","category":"城市街拍","cn":"海口市龙华区长堤路，靠近海口钟楼和海甸溪。路的一边有老城区的建筑，另一边是江边夜景，白天和晚上的感觉很不同。可以从钟楼附近慢慢走，一路看船、车流和灯光。","en":"You can find it at Changdi Road in Longhua District, near Haikou Clock Tower and Haidian Creek. This road connects the older city with a lively waterfront. Walk from the Clock Tower area toward the creek to see boats, traffic, and the city lighting up at night.","location":"海口市龙华区长堤路，靠近海口钟楼和海甸溪","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%95%BF%E5%A0%A4%E8%B7%AF%E6%BB%A8%E6%B0%B4%E8%A1%97%E5%8C%BA","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%95%BF%E5%A0%A4%E8%B7%AF%E6%BB%A8%E6%B0%B4%E8%A1%97%E5%8C%BA"},{"id":22,"name":"海口东坡老码头","enName":"Dongpo Old Wharf","city":"海口","category":"城市街拍","cn":"海口市美兰区碧海大道98号，海甸三西路附近。这里不是老旧码头遗址，而是有宋风元素的新休闲商业街区，有吃喝、拍照和夜间游船。晚上灯笼、古风建筑和世纪大桥一起入镜，比白天更有氛围。","en":"It is at No. 98 Bihai Avenue in Meilan District, near Haidian Third West Road. This is a newer waterfront leisure area with Song-dynasty-inspired design, food, and evening boat trips. Lanterns and the nearby Century Bridge make it particularly atmospheric after dark.","location":"海口市美兰区碧海大道98号，海甸三西路附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8F%A3%E4%B8%9C%E5%9D%A1%E8%80%81%E7%A0%81%E5%A4%B4","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8F%A3%E4%B8%9C%E5%9D%A1%E8%80%81%E7%A0%81%E5%A4%B4"},{"id":23,"name":"Matata Coffee（龙兴路）","enName":"Matata Coffee (Longxing Road)","city":"海口","category":"城市街拍","cn":"海口市龙华区龙兴路，柏园雅居附近。这家咖啡馆是龙兴路街拍氛围的代表之一，门口的小桌椅经常坐满来聊天的年轻人。比起喝完就走，更适合坐在室外看街景、感受这条街的热闹。","en":"You can find it at Longxing Road in Longhua District, close to Baiyuan Yaju. This café is part of what made Longxing Road trendy. People gather at the small outdoor tables, so it's a fun stop for coffee and people-watching between photos.","location":"海口市龙华区龙兴路，柏园雅居附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3Matata%20Coffee%EF%BC%88%E9%BE%99%E5%85%B4%E8%B7%AF%EF%BC%89","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3Matata%20Coffee%EF%BC%88%E9%BE%99%E5%85%B4%E8%B7%AF%EF%BC%89"},{"id":24,"name":"斑马院子（龙兴路）","enName":"Zebra Courtyard (Longxing Road)","city":"海口","category":"城市街拍","cn":"海口市龙华区龙兴路的斑马院子店铺。它是龙兴路较早受欢迎的小店之一，烘焙和有设计感的店面很受拍照的人喜欢。适合和龙兴路一起逛，不需要把它当成单独的半天景点。","en":"You can find it at Zebra Courtyard on Longxing Road, Longhua District. One of the street's earlier popular shops, known for baked treats and a photogenic storefront. Drop in while exploring Longxing Road rather than making a separate trip.","location":"海口市龙华区龙兴路的斑马院子店铺","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%96%91%E9%A9%AC%E9%99%A2%E5%AD%90%EF%BC%88%E9%BE%99%E5%85%B4%E8%B7%AF%EF%BC%89","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%96%91%E9%A9%AC%E9%99%A2%E5%AD%90%EF%BC%88%E9%BE%99%E5%85%B4%E8%B7%AF%EF%BC%89"},{"id":25,"name":"席地而坐（龙兴路）","enName":"Sitting & Drinking (Longxing Road)","city":"海口","category":"城市街拍","cn":"海口市龙华区龙兴路5号附近。这家店白天偏咖啡，晚上又有餐酒吧的社交感觉，是龙兴路从午后逛街切换到夜生活的代表。想拍街头生活照，也可以留意它的门口和周边小巷。","en":"It is around No. 5 Longxing Road, Longhua District. A café-meets-bar that shows Longxing Road's daytime-to-evening personality. It's a nice stop for a drink and some lively street photos, especially later in the day.","location":"海口市龙华区龙兴路5号附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%B8%AD%E5%9C%B0%E8%80%8C%E5%9D%90%EF%BC%88%E9%BE%99%E5%85%B4%E8%B7%AF%EF%BC%89","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%B8%AD%E5%9C%B0%E8%80%8C%E5%9D%90%EF%BC%88%E9%BE%99%E5%85%B4%E8%B7%AF%EF%BC%89"},{"id":26,"name":"手帐咖啡好天气（龙兴路）","enName":"Good Weather Journal Café (Longxing Road)","city":"海口","category":"城市街拍","cn":"海口市龙华区龙兴路上的手帐主题小店。和普通咖啡店不一样，这里更吸引喜欢手帐、文具和手作的人。可以看看小物件、拍些细节照片，适合喜欢文艺小店的朋友。","en":"You can find it at A stationery-themed café along Longxing Road, Longhua District. This is a fun little stop if you like notebooks, stationery, and handmade details. It's more about browsing creative objects than checking off another coffee shop.","location":"海口市龙华区龙兴路上的手帐主题小店","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%89%8B%E5%B8%90%E5%92%96%E5%95%A1%E5%A5%BD%E5%A4%A9%E6%B0%94%EF%BC%88%E9%BE%99%E5%85%B4%E8%B7%AF%EF%BC%89","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%89%8B%E5%B8%90%E5%92%96%E5%95%A1%E5%A5%BD%E5%A4%A9%E6%B0%94%EF%BC%88%E9%BE%99%E5%85%B4%E8%B7%AF%EF%BC%89"},{"id":27,"name":"Hippo Gelato（龙兴路）","enName":"Hippo Gelato (Longxing Road)","city":"海口","category":"城市街拍","cn":"海口市龙华区龙兴路一带的冰淇淋小店。逛龙兴路逛累了，可以顺路来吃一份意式冰淇淋。它是街拍路线上的小休息站，不必特地为一家冰淇淋店跑很远。","en":"You can find it at A gelato shop in the Longxing Road area of Longhua District. A simple treat while walking around Longxing Road. Grab some gelato, take a break, and carry on exploring the cafés and pretty shopfronts.","location":"海口市龙华区龙兴路一带的冰淇淋小店","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3Hippo%20Gelato%EF%BC%88%E9%BE%99%E5%85%B4%E8%B7%AF%EF%BC%89","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3Hippo%20Gelato%EF%BC%88%E9%BE%99%E5%85%B4%E8%B7%AF%EF%BC%89"},{"id":28,"name":"金盘夜市","enName":"Jinpan Night Market","city":"海口","category":"美食夜生活","cn":"海口市龙华区金盘路8号。这座夜市更有附近居民出来吃宵夜的感觉，摊位多，价格和选择比较接地气。晚上来试试烤串、海南小吃，比去商场吃饭更能感受本地生活。","en":"It is at No. 8 Jinpan Road, Longhua District, Haikou. This night market feels like where nearby residents go for supper. Expect barbecue, local snacks, and a lively, everyday atmosphere rather than a polished tourist show.","location":"海口市龙华区金盘路8号","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%87%91%E7%9B%98%E5%A4%9C%E5%B8%82","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%87%91%E7%9B%98%E5%A4%9C%E5%B8%82"},{"id":29,"name":"寻尝里夜市","enName":"Xunchangli Night Market","city":"海口","category":"美食夜生活","cn":"海口市秀英区美俗路35号。这里是一片集中的夜市小吃区，适合几个人一起点不同的东西分着吃。比起只找一家餐厅，边走边选更有乐趣，尤其适合不知道要吃什么的时候。","en":"It is at No. 35 Meisu Road, Xiuying District, Haikou. This is an easy place to sample different foods in one evening. Go with friends, pick a few stalls, share dishes, and see what you discover.","location":"海口市秀英区美俗路35号","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%AF%BB%E5%B0%9D%E9%87%8C%E5%A4%9C%E5%B8%82","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%AF%BB%E5%B0%9D%E9%87%8C%E5%A4%9C%E5%B8%82"},{"id":30,"name":"福地夜巷","enName":"Fudi Night Lane","city":"海口","category":"美食夜生活","cn":"海口市琼山区忠介路86号，府城老城区内。这里把传统老城区和热闹夜市结合起来，逛完府城老街可以直接接着吃宵夜。附近有不少海南本地小吃，是晚上体验府城生活的方便一站。","en":"It is at No. 86 Zhongjie Road in Qiongshan District, within old Fucheng. This night market is right in old Fucheng, so you can explore the older streets and then stay for snacks. It's a convenient way to experience the neighborhood after dark.","location":"海口市琼山区忠介路86号，府城老城区内","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E7%A6%8F%E5%9C%B0%E5%A4%9C%E5%B7%B7","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E7%A6%8F%E5%9C%B0%E5%A4%9C%E5%B7%B7"},{"id":31,"name":"桂林洋大学城夜市","enName":"Guilinyang University Town Night Market","city":"海口","category":"美食夜生活","cn":"海口市美兰区桂林洋大学城一带。这里以学生为主，夜市的感觉比较年轻，常见各种实惠小吃和饮料。适合想看看海南大学城夜生活、顺便找点便宜好吃东西的人。","en":"You can find it at The Guilinyang university district in Meilan District, Haikou. The crowd here is mostly students, and the food is casual and affordable. Visit for the lively university-night-market vibe and an easy late snack.","location":"海口市美兰区桂林洋大学城一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%A1%82%E6%9E%97%E6%B4%8B%E5%A4%A7%E5%AD%A6%E5%9F%8E%E5%A4%9C%E5%B8%82","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%A1%82%E6%9E%97%E6%B4%8B%E5%A4%A7%E5%AD%A6%E5%9F%8E%E5%A4%9C%E5%B8%82"},{"id":32,"name":"丁村万人海鲜广场","enName":"Dingcun Seafood Square","city":"海口","category":"美食夜生活","cn":"海口市琼山区丁村一带的万人海鲜广场。和普通餐厅不同，这里可以先挑海鲜，再按自己的口味让店家加工。适合几个朋友一起点鱼、虾、蟹，体验海南人热热闹闹吃海鲜的方式。","en":"You can find it at Dingcun Seafood Square in Qiongshan District, Haikou. You choose seafood first and then have it cooked the way you like. It's especially fun with a group, sharing fish, prawns, and crab around a big table.","location":"海口市琼山区丁村一带的万人海鲜广场","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%81%E6%9D%91%E4%B8%87%E4%BA%BA%E6%B5%B7%E9%B2%9C%E5%B9%BF%E5%9C%BA","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%81%E6%9D%91%E4%B8%87%E4%BA%BA%E6%B5%B7%E9%B2%9C%E5%B9%BF%E5%9C%BA"},{"id":33,"name":"东门市场","enName":"Dongmen Market","city":"海口","category":"美食夜生活","cn":"海口市美兰区博爱南路和东门市场周边。这里不是精致的网红打卡点，而是能看到海南人真实买菜生活的市场。鱼虾、热带水果、香料和各种食材都很有地方特色，早上来会更有意思。","en":"It is around Dongmen Market and Bo'ai South Road in Meilan District. This is a real local market, not a polished photo attraction. Come in the morning to see seafood, tropical fruit, spices, and the bustle of everyday shopping.","location":"海口市美兰区博爱南路和东门市场周边","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%9C%E9%97%A8%E5%B8%82%E5%9C%BA","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%9C%E9%97%A8%E5%B8%82%E5%9C%BA"},{"id":34,"name":"观澜湖美食自助夜市","enName":"Mission Hills Food Night Market","city":"海口","category":"美食夜生活","cn":"海口市龙华区观澜湖新城石矿湖附近。它和传统夜市不同，走的是买票后集中尝多种风味小吃的模式，节假日和周末比较热闹。可能还有表演和游乐安排，去之前一定要确认当期有没有开场。","en":"It is near Shikuang Lake in Mission Hills Centreville, Longhua District. Unlike a normal night market, this one has offered a ticketed all-you-can-try food experience. Entertainment and opening dates can change, so check the current event schedule first.","location":"海口市龙华区观澜湖新城石矿湖附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%A7%82%E6%BE%9C%E6%B9%96%E7%BE%8E%E9%A3%9F%E8%87%AA%E5%8A%A9%E5%A4%9C%E5%B8%82","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%A7%82%E6%BE%9C%E6%B9%96%E7%BE%8E%E9%A3%9F%E8%87%AA%E5%8A%A9%E5%A4%9C%E5%B8%82"},{"id":35,"name":"上邦百汇城","enName":"Shangbang Baihuicheng","city":"海口","category":"美食夜生活","cn":"海口市龙华区国贸片区的上邦百汇城。这是市中心比较方便约朋友的餐饮购物区，周围选择多。它不是必须专程旅游的地标，不过热得不想走户外时，来吃饭、看电影或喝咖啡很实用。","en":"You can find it at Shangbang Baihuicheng in Haikou's Guomao district. A convenient central place for food, shopping, and meeting friends. It's not a must-see landmark, but it's handy when it's too hot to spend the whole day outdoors.","location":"海口市龙华区国贸片区的上邦百汇城","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%8A%E9%82%A6%E7%99%BE%E6%B1%87%E5%9F%8E","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%8A%E9%82%A6%E7%99%BE%E6%B1%87%E5%9F%8E"},{"id":36,"name":"友谊阳光城","enName":"Friendship Sunshine City","city":"海口","category":"美食夜生活","cn":"海口市龙华区金龙路的友谊阳光城。国贸片区的大型商场，餐饮、娱乐和购物集中，最适合用来躲太阳或下雨天安排活动。想找一个集合地点再去附近逛街，也很方便。","en":"You can find it at Youyi Sunshine City on Jinlong Road, Longhua District. A large shopping mall in the Guomao area, useful for food, entertainment, and escaping the midday heat. It's also an easy meeting point.","location":"海口市龙华区金龙路的友谊阳光城","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%8F%8B%E8%B0%8A%E9%98%B3%E5%85%89%E5%9F%8E","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%8F%8B%E8%B0%8A%E9%98%B3%E5%85%89%E5%9F%8E"},{"id":37,"name":"cdf海口国际免税城","enName":"CDF Haikou International Duty Free City","city":"海口","category":"美食夜生活","cn":"海口市秀英区滨海大道西段，新海港附近。这里最特别的是商场规模很大，适合喜欢国际品牌和免税购物的人。它和看风景的景区不一样，更适合把购物、吃饭和看大型室内空间安排在一起。","en":"It is on western Binhai Avenue in Xiuying District, near Xinhai Port. This is a huge duty-free shopping complex near the port. Visit for international brands and indoor shopping rather than beaches or nature.","location":"海口市秀英区滨海大道西段，新海港附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3cdf%E6%B5%B7%E5%8F%A3%E5%9B%BD%E9%99%85%E5%85%8D%E7%A8%8E%E5%9F%8E","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3cdf%E6%B5%B7%E5%8F%A3%E5%9B%BD%E9%99%85%E5%85%8D%E7%A8%8E%E5%9F%8E"},{"id":38,"name":"海口湾演艺中心","enName":"Haikou Bay Performing Arts Center","city":"海口","category":"美食夜生活","cn":"海口市龙华区滨海大道海口湾一带。海口湾演艺中心适合有演出时专门来，音乐会、剧场节目才是重点。最好先看节目单和票务，别只为了打卡建筑跑一趟。","en":"It is along Binhai Avenue near Haikou Bay, Longhua District. The real reason to visit is a concert or performance, not just the building. Check the program and tickets before planning your evening.","location":"海口市龙华区滨海大道海口湾一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8F%A3%E6%B9%BE%E6%BC%94%E8%89%BA%E4%B8%AD%E5%BF%83","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8F%A3%E6%B9%BE%E6%BC%94%E8%89%BA%E4%B8%AD%E5%BF%83"},{"id":39,"name":"万绿园","enName":"Evergreen Park (Wanlüyuan)","city":"海口","category":"海滨日落","cn":"海口市龙华区滨海大道38号，海口湾边。万绿园是海口人经常去散步、跑步、野餐的大草坪，天气舒服时很有生活气。比起拍一个固定景点，更适合带朋友放松，看草地、椰树和海边城市风景。","en":"It is at No. 38 Binhai Avenue, Longhua District, right by Haikou Bay. This is where locals picnic, run, and relax on big lawns near the bay. Come to slow down and see everyday Haikou life rather than chase a famous landmark.","location":"海口市龙华区滨海大道38号，海口湾边","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%87%E7%BB%BF%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%87%E7%BB%BF%E5%9B%AD"},{"id":40,"name":"世纪公园","enName":"Century Park","city":"海口","category":"海滨日落","cn":"海口市龙华区世纪公园，靠近世纪大桥南端。这里最有代表性的画面就是高高的世纪大桥和海口湾放在一起。傍晚能看桥上的车灯、海面和城市建筑，特别适合拍海口夜景。","en":"You can find it at Century Park in Longhua District, near the south end of Century Bridge. The best view combines Century Bridge, the bay, and Haikou's skyline. Come at dusk when the bridge lights and city reflections begin to appear.","location":"海口市龙华区世纪公园，靠近世纪大桥南端","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%96%E7%BA%AA%E5%85%AC%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%96%E7%BA%AA%E5%85%AC%E5%9B%AD"},{"id":41,"name":"海口湾滨海步道","enName":"Haikou Bay Waterfront Walk","city":"海口","category":"海滨日落","cn":"海口市龙华区海口湾沿岸，世纪公园至云洞图书馆一带。这条路线适合边走边看现代海口，不需要门票，也不必专门安排项目。海风、桥梁、海边建筑和落日都能拍到，晚上散步也很舒服。","en":"It is along Haikou Bay in Longhua District, around Century Park and Cloud Cave Library. This waterfront walk gives you bridges, modern buildings, and sea views in one easy route. It's free, relaxed, and especially pleasant toward sunset.","location":"海口市龙华区海口湾沿岸，世纪公园至云洞图书馆一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8F%A3%E6%B9%BE%E6%BB%A8%E6%B5%B7%E6%AD%A5%E9%81%93","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8F%A3%E6%B9%BE%E6%BB%A8%E6%B5%B7%E6%AD%A5%E9%81%93"},{"id":42,"name":"西秀海滩","enName":"Xixiu Beach","city":"海口","category":"海滨日落","cn":"海口市秀英区滨海大道173号附近。这里和一般海滩不同，能看到帆船帆板训练的场景，是海南海上运动很有代表性的地方。想体验帆船要找正规机构预约，光是海边看船也挺有意思。","en":"It is around No. 173 Binhai Avenue, Xiuying District. This beach is known for sailing and windsurfing, so you might see boats and training activities. Book a proper operator if you want to try the sport yourself.","location":"海口市秀英区滨海大道173号附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%A5%BF%E7%A7%80%E6%B5%B7%E6%BB%A9","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%A5%BF%E7%A7%80%E6%B5%B7%E6%BB%A9"},{"id":43,"name":"假日海滩","enName":"Holiday Beach","city":"海口","category":"海滨日落","cn":"海口市秀英区滨海大道西段的假日海滩。这里是一条有椰树、沙滩和海风的城市海岸，适合傍晚散步或者坐着看落日。海口的海水条件和三亚不同，来这里主要是休闲看海，不要默认能安全游泳。","en":"You can find it at Holiday Beach on western Binhai Avenue, Xiuying District. A classic city beach for coconut trees, sea breezes, and sunsets. Come mainly to relax by the water; swimming conditions are not the same as at every resort beach.","location":"海口市秀英区滨海大道西段的假日海滩","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%81%87%E6%97%A5%E6%B5%B7%E6%BB%A9","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%81%87%E6%97%A5%E6%B5%B7%E6%BB%A9"},{"id":44,"name":"观海台","enName":"Guanhaitai Seaside Viewpoint","city":"海口","category":"海滨日落","cn":"海口市秀英区西海岸滨海大道沿线的观海台。这是西海岸比较容易停下来欣赏海景的地方，海面开阔，适合看夕阳。可以和假日海滩、西秀海滩安排在同一趟路线上，不必单独开车来回折腾。","en":"You can find it at Guanhaitai on the western coastal stretch of Binhai Avenue. A simple open-water viewpoint on Haikou's west coast, best around sunset. Combine it with nearby beaches instead of making a separate long trip.","location":"海口市秀英区西海岸滨海大道沿线的观海台","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%A7%82%E6%B5%B7%E5%8F%B0","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%A7%82%E6%B5%B7%E5%8F%B0"},{"id":45,"name":"白沙门公园","enName":"Baishamen Park","city":"海口","category":"海滨日落","cn":"海口市美兰区海甸六东路一带的白沙门公园。这里更像海口人的海边生活公园，草地、树荫和休闲步道都有。适合早晚散步或带朋友轻松运动，不是那种需要排队拍照的大景区。","en":"You can find it at Baishamen Park near Haidian Sixth East Road, Meilan District. A local seaside park with lawns, shade, and walking paths. It's best for a relaxed stroll or light exercise rather than a big sightseeing itinerary.","location":"海口市美兰区海甸六东路一带的白沙门公园","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E7%99%BD%E6%B2%99%E9%97%A8%E5%85%AC%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E7%99%BD%E6%B2%99%E9%97%A8%E5%85%AC%E5%9B%AD"},{"id":46,"name":"拾贝公园","enName":"Shibei Park","city":"海口","category":"海滨日落","cn":"海口市秀英区西海岸沿线的拾贝公园。这片滨海公园的特点是空间开阔、路好走，适合吹风和拍海边散步的生活照。若本来就在西海岸，可以顺路停一停。","en":"You can find it at Shibei Park on the west coast of Xiuying District. This is an open coastal park for an easy walk and breezy photos. It's worth a stop if you're already exploring Haikou's western shoreline.","location":"海口市秀英区西海岸沿线的拾贝公园","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%8B%BE%E8%B4%9D%E5%85%AC%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%8B%BE%E8%B4%9D%E5%85%AC%E5%9B%AD"},{"id":47,"name":"金沙湾滨海公园","enName":"Jinsha Bay Coastal Park","city":"海口","category":"海滨日落","cn":"海口市秀英区金沙湾海岸一带。海面和沙滩比较开阔，天气好时适合野餐、拍日落和放空。这里的看点不是密集娱乐项目，而是能找块空地舒服地坐一会儿。","en":"You can find it at The Jinshawan coast in Xiuying District, Haikou. The broad coastline is best for a picnic, an open sunset view, or simply sitting by the sea. It's about space and quiet rather than lots of attractions.","location":"海口市秀英区金沙湾海岸一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%87%91%E6%B2%99%E6%B9%BE%E6%BB%A8%E6%B5%B7%E5%85%AC%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%87%91%E6%B2%99%E6%B9%BE%E6%BB%A8%E6%B5%B7%E5%85%AC%E5%9B%AD"},{"id":48,"name":"桂林洋海滨","enName":"Guilinyang Coast","city":"海口","category":"海滨日落","cn":"海口市美兰区桂林洋海岸一带。这里离市中心有一段距离，海岸感觉相对自然，游客聚集程度低一些。适合喜欢安静海景和海岸摄影的人，但去之前要了解交通、天气和海浪情况。","en":"You can find it at The Guilinyang coast in Meilan District. This stretch feels more natural and less crowded than the central bay. Go for quiet coastal scenery, but check access, weather, and sea conditions first.","location":"海口市美兰区桂林洋海岸一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%A1%82%E6%9E%97%E6%B4%8B%E6%B5%B7%E6%BB%A8","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%A1%82%E6%9E%97%E6%B4%8B%E6%B5%B7%E6%BB%A8"},{"id":49,"name":"东寨港红树林","enName":"Dongzhai Harbor Mangroves","city":"海口","category":"自然体验","cn":"海口市美兰区演丰镇红林路，东寨港湿地一带。这里不是普通森林，而是树根长在潮水里的红树林湿地。跟着正规观景路线看树根、滩涂和鸟类，很容易发现海南不只有椰树和沙滩。","en":"You can find it at Honglin Road in Yanfeng Town, Meilan District, by Dongzhai Harbor. These trees grow in tidal water, creating a very different kind of forest. Follow the proper viewing route to see their roots, mudflats, and birds.","location":"海口市美兰区演丰镇红林路，东寨港湿地一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%9C%E5%AF%A8%E6%B8%AF%E7%BA%A2%E6%A0%91%E6%9E%97","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%9C%E5%AF%A8%E6%B8%AF%E7%BA%A2%E6%A0%91%E6%9E%97"},{"id":50,"name":"三卿村","enName":"Sanqing Village","city":"海口","category":"自然体验","cn":"海口市秀英区石山镇，火山口地质公园附近。三卿村的石屋、石墙和小路很多都是用火山石砌成的，走进去有一种被黑色石头包围的感觉。很适合和火山口公园安排在同一天，看完自然地貌再看火山村落。","en":"You can find it at Shishan Town, Xiuying District, close to the volcano park. Many houses, lanes, and walls here are built from volcanic stone. Pair it with the volcano park to see how the same rock shaped both the land and village life.","location":"海口市秀英区石山镇，火山口地质公园附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%89%E5%8D%BF%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E4%B8%89%E5%8D%BF%E6%9D%91"},{"id":51,"name":"美社村","enName":"Meishe Village","city":"海口","category":"自然体验","cn":"海口市秀英区石山镇美社村。这里最值得看的是火山岩石屋和海南乡村的老巷子，不是大型商业景点。适合慢慢走，看看当地人怎么在火山石环境里生活。","en":"You can find it at Meishe Village in Shishan Town, Xiuying District. This village is known for traditional volcanic-stone buildings and old lanes. It's a quiet place to see how people have lived in Haikou's volcanic countryside.","location":"海口市秀英区石山镇美社村","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E7%BE%8E%E7%A4%BE%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E7%BE%8E%E7%A4%BE%E6%9D%91"},{"id":52,"name":"施茶村","enName":"Shicha Village","city":"海口","category":"自然体验","cn":"海口市秀英区石山镇施茶村。这里把火山石地貌和农业结合起来，石斛种植是比较有代表性的特色。喜欢乡村体验的人可以了解当地农场怎么利用火山岩环境种植物。","en":"You can find it at Shicha Village in Shishan Town, Xiuying District. Shicha is interesting for its volcanic-stone farming, especially the way locals grow dendrobium orchids. It's more of a countryside experience than a typical tourist attraction.","location":"海口市秀英区石山镇施茶村","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%96%BD%E8%8C%B6%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%96%BD%E8%8C%B6%E6%9D%91"},{"id":53,"name":"荔枝花海·火山营地","enName":"Lychee Blossom Volcanic Camp","city":"海口","category":"自然体验","cn":"海口市秀英区永兴镇荔枝花海火山营地。荔枝季这里的看点不只是露营，还可以体验荔枝林和当地火山荔枝。采摘有季节限制，最好在活动开放时来，不要以为一年四季都能摘果子。","en":"You can find it at Lychee Flower Sea Volcano Camp in Yongxing Town, Xiuying District. During lychee season, the orchards are the main attraction, and picking activities may be available. Camping and events vary by date, so check the season before coming.","location":"海口市秀英区永兴镇荔枝花海火山营地","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%8D%94%E6%9E%9D%E8%8A%B1%E6%B5%B7%C2%B7%E7%81%AB%E5%B1%B1%E8%90%A5%E5%9C%B0","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%8D%94%E6%9E%9D%E8%8A%B1%E6%B5%B7%C2%B7%E7%81%AB%E5%B1%B1%E8%90%A5%E5%9C%B0"},{"id":54,"name":"自由大陆营地","enName":"Free Continent Camp","city":"海口","category":"自然体验","cn":"海口市龙华区城西镇沙坡郊野湿地公园附近。它是湿地旁的休闲露营地，有草地、营地餐食和窑烤面包之类的特色体验。比较适合几个人提前约好来聚会，具体开放和活动要临时确认。","en":"It is near Shapo Wetland Park in Chengxi Town, Longhua District. This campsite sits by a wetland and has offered outdoor meals, gatherings, and oven-baked bread. It's better for a planned group outing; confirm the current schedule first.","location":"海口市龙华区城西镇沙坡郊野湿地公园附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%87%AA%E7%94%B1%E5%A4%A7%E9%99%86%E8%90%A5%E5%9C%B0","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%87%AA%E7%94%B1%E5%A4%A7%E9%99%86%E8%90%A5%E5%9C%B0"},{"id":55,"name":"海口演艺新空间·泊岸艺术中心","enName":"Bo'an Art Center","city":"海口","category":"自然体验","cn":"海口市龙华区滨海大道42号海口演艺新空间内，万绿园旁。泊岸艺术中心以展览和创意活动为主，艺术家作品、空间设计和旁边的剧场可以一起看。这里不是每天都有一样的内容，先查当期展览或演出，选自己感兴趣的时间去。","en":"It is inside Haikou Performing Arts New Space at No. 42 Binhai Avenue, Longhua District, beside Evergreen Park. This arts venue is part of a larger performance complex near Evergreen Park. Look for exhibitions, creative events, and theater programs; check the current schedule before visiting.","location":"海口市龙华区滨海大道42号海口演艺新空间内，万绿园旁","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8F%A3%E6%BC%94%E8%89%BA%E6%96%B0%E7%A9%BA%E9%97%B4%C2%B7%E6%B3%8A%E5%B2%B8%E8%89%BA%E6%9C%AF%E4%B8%AD%E5%BF%83","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8F%A3%E6%BC%94%E8%89%BA%E6%96%B0%E7%A9%BA%E9%97%B4%C2%B7%E6%B3%8A%E5%B2%B8%E8%89%BA%E6%9C%AF%E4%B8%AD%E5%BF%83"},{"id":56,"name":"冯小刚电影公社","enName":"Feng Xiaogang Movie Town","city":"海口","category":"自然体验","cn":"海口市龙华区观澜湖旅游度假区电影公社内。这里特别适合喜欢复古街拍的人，能在同一个园区看到不同年代风格的街道、招牌和建筑。穿复古服装来拍照更有趣，拍出来像电影剧照。","en":"It is inside the Movie Town at Mission Hills, Longhua District. Movie Town is great for retro photos, with streets and storefronts styled after different periods. Dressing up makes the experience even more fun—your pictures can look like movie stills.","location":"海口市龙华区观澜湖旅游度假区电影公社内","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%86%AF%E5%B0%8F%E5%88%9A%E7%94%B5%E5%BD%B1%E5%85%AC%E7%A4%BE","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E5%86%AF%E5%B0%8F%E5%88%9A%E7%94%B5%E5%BD%B1%E5%85%AC%E7%A4%BE"},{"id":57,"name":"长影奇幻乐园","enName":"Changying Fantasy Park","city":"海口","category":"自然体验","cn":"海口市秀英区长影奇幻乐园园区。这里主要是游乐和光影主题体验，适合想玩设施、看表演的人。项目开放情况可能变化，最好先确认现在有哪些设施营业，再决定值不值得专程来。","en":"You can find it at Changying Fantasy Park in Xiuying District, Haikou. This is for rides, entertainment, and themed attractions. Check which facilities are operating before making a special trip, since availability can change.","location":"海口市秀英区长影奇幻乐园园区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%95%BF%E5%BD%B1%E5%A5%87%E5%B9%BB%E4%B9%90%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E9%95%BF%E5%BD%B1%E5%A5%87%E5%B9%BB%E4%B9%90%E5%9B%AD"},{"id":58,"name":"观澜湖旅游度假区","enName":"Mission Hills Resort","city":"海口","category":"自然体验","cn":"海口市龙华区观澜湖旅游度假区。这一带以高尔夫、度假酒店和配套休闲为主，更适合想安排半天到一天轻松活动的人。和年轻人街拍路线不同，主要是度假和运动体验。","en":"You can find it at Mission Hills Resort in Longhua District, Haikou. Mission Hills is more about golf, resort facilities, and a relaxed day out than street photography. Go if you're in the mood for leisure or sport.","location":"海口市龙华区观澜湖旅游度假区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%A7%82%E6%BE%9C%E6%B9%96%E6%97%85%E6%B8%B8%E5%BA%A6%E5%81%87%E5%8C%BA","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E8%A7%82%E6%BE%9C%E6%B9%96%E6%97%85%E6%B8%B8%E5%BA%A6%E5%81%87%E5%8C%BA"},{"id":59,"name":"海南热带野生动植物园","enName":"Hainan Tropical Wildlife Park","city":"海口","category":"自然体验","cn":"海口市秀英区东山镇海南热带野生动植物园。这里可以看海南热带植物和各种动物，适合喜欢动物或带孩子的朋友。园区比较大，天气热时建议早去，提前看好园内交通和游览路线。","en":"You can find it at Hainan Tropical Wildlife and Botanical Garden in Dongshan Town, Xiuying District. This large park combines animals with tropical greenery. Go early to avoid the hottest hours, and check the park route so you can cover the areas you want to see.","location":"海口市秀英区东山镇海南热带野生动植物园","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8D%97%E7%83%AD%E5%B8%A6%E9%87%8E%E7%94%9F%E5%8A%A8%E6%A4%8D%E7%89%A9%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8D%97%E7%83%AD%E5%B8%A6%E9%87%8E%E7%94%9F%E5%8A%A8%E6%A4%8D%E7%89%A9%E5%9B%AD"},{"id":60,"name":"海口湾游船（东坡老码头出发）","enName":"Haikou Bay Cruise (Dongpo Wharf)","city":"海口","category":"自然体验","cn":"海口市美兰区碧海大道东坡老码头游船码头。这不是站在岸上看海，而是坐船从水上看世纪大桥、海口湾和城市灯光。夜游比较有氛围，但班次可能因天气调整，要先看当日船票和出航通知。","en":"You can find it at The cruise pier at Dongpo Old Wharf on Bihai Avenue, Meilan District. See Haikou from the water instead of the shore. The evening cruise gives you views of Century Bridge and the skyline, but departures depend on tickets and weather.","location":"海口市美兰区碧海大道东坡老码头游船码头","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8F%A3%E6%B9%BE%E6%B8%B8%E8%88%B9%EF%BC%88%E4%B8%9C%E5%9D%A1%E8%80%81%E7%A0%81%E5%A4%B4%E5%87%BA%E5%8F%91%EF%BC%89","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%B5%B7%E5%8F%A3%E6%B5%B7%E5%8F%A3%E6%B9%BE%E6%B8%B8%E8%88%B9%EF%BC%88%E4%B8%9C%E5%9D%A1%E8%80%81%E7%A0%81%E5%A4%B4%E5%87%BA%E5%8F%91%EF%BC%89"},{"id":61,"name":"铜鼓岭","enName":"Tongguling Scenic Area","city":"文昌","category":"海南环岛","cn":"文昌市龙楼镇铜鼓岭景区，靠近月亮湾。这里最大的卖点是登高后能同时看到绿色山坡、弯弯的月亮湾和蓝色大海。天气晴朗时层次特别漂亮，比站在普通海滩上看海更震撼。","en":"You can find it at Tongguling in Longlou Town, Wenchang, above Moon Bay. The view is the star: green hills, the curved Moon Bay, and blue sea all in one panorama. On a clear day, it's much more dramatic than a regular beach view.","location":"文昌市龙楼镇铜鼓岭景区，靠近月亮湾","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E9%93%9C%E9%BC%93%E5%B2%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E9%93%9C%E9%BC%93%E5%B2%AD"},{"id":62,"name":"石头公园","enName":"Stone Park","city":"文昌","category":"海南环岛","cn":"文昌市龙楼镇铜鼓岭附近的石头公园海岸。这里不是平整沙滩，而是一大片被海浪冲刷过的巨石，石头形状和浪花都很特别。适合拍气势比较强的海岸照片，但岩石湿滑，不要靠近危险浪区。","en":"You can find it at Stone Park on the coast near Tongguling, Longlou Town, Wenchang. Huge weathered rocks and crashing waves make this coastline look dramatic. It's wonderful for landscape photos, but the rocks can be slippery and the surf dangerous.","location":"文昌市龙楼镇铜鼓岭附近的石头公园海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E7%9F%B3%E5%A4%B4%E5%85%AC%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E7%9F%B3%E5%A4%B4%E5%85%AC%E5%9B%AD"},{"id":63,"name":"东郊椰林","enName":"Dongjiao Coconut Grove","city":"文昌","category":"海南环岛","cn":"文昌市东郊镇东郊椰林海岸。这里椰子树特别密，很多地方一抬头就是椰叶，走几步又能看到大海。想让外国朋友感受最典型的海南热带海岛画面，来这里很合适。","en":"You can find it at Dongjiao Coconut Grove in Dongjiao Town, Wenchang. Tall coconut palms grow densely beside the sea here. If you want that classic tropical-island feeling—palm leaves overhead and the coast just steps away—this is the place.","location":"文昌市东郊镇东郊椰林海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E4%B8%9C%E9%83%8A%E6%A4%B0%E6%9E%97","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E4%B8%9C%E9%83%8A%E6%A4%B0%E6%9E%97"},{"id":64,"name":"木兰湾风车海岸","enName":"Mulan Bay Windmill Coast","city":"文昌","category":"海南环岛","cn":"文昌市铺前镇木兰湾海岸和木兰灯塔附近。这一带很适合自驾，海边能看到风车、灯塔和长长的海岸线。不是那种店铺很多的热闹景区，重点是沿途风景和看海，天气好时很有电影感。","en":"You can find it at Mulan Bay near Mulan Lighthouse in Puqian Town, Wenchang. The drive is part of the fun, with wind turbines, a lighthouse, and a wide coastal landscape. It's more about the scenery than shops or activities.","location":"文昌市铺前镇木兰湾海岸和木兰灯塔附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E6%9C%A8%E5%85%B0%E6%B9%BE%E9%A3%8E%E8%BD%A6%E6%B5%B7%E5%B2%B8","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E6%9C%A8%E5%85%B0%E6%B9%BE%E9%A3%8E%E8%BD%A6%E6%B5%B7%E5%B2%B8"},{"id":65,"name":"淇水湾海滩","enName":"Qishui Bay Beach","city":"文昌","category":"海南环岛","cn":"文昌市龙楼镇淇水湾，文昌航天发射场附近。这片海滩除了海景漂亮，还有一个很特别的理由：遇到合适的发射任务，有些观景位置能远远看到火箭升空。平时可以看海，想看发射必须提前查官方通告。","en":"You can find it at Qishui Bay in Longlou Town, near the Wenchang Space Launch Site. This beach has a special claim to fame: during some launches, you may be able to watch a rocket rise in the distance. On normal days it's a scenic beach; always check official launch notices.","location":"文昌市龙楼镇淇水湾，文昌航天发射场附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E6%B7%87%E6%B0%B4%E6%B9%BE%E6%B5%B7%E6%BB%A9","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E6%B7%87%E6%B0%B4%E6%B9%BE%E6%B5%B7%E6%BB%A9"},{"id":66,"name":"文昌航天发射场相关参观体验","enName":"Wenchang Space Launch Visitor Experience","city":"文昌","category":"海南环岛","cn":"文昌市龙楼镇文昌航天发射场周边指定参观区域。这里最吸引人的不是普通展馆，而是能近距离了解中国航天发射基地的真实环境。参观范围受管理规定限制，不能想进哪里就进哪里，最好按正规渠道预约。","en":"You can find it at Designated visitor areas near the Wenchang Space Launch Site in Longlou Town. This is one of China's major rocket-launch locations, so space fans will love learning about the real launch facilities. Access is controlled, and visits must follow approved arrangements.","location":"文昌市龙楼镇文昌航天发射场周边指定参观区域","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E6%96%87%E6%98%8C%E8%88%AA%E5%A4%A9%E5%8F%91%E5%B0%84%E5%9C%BA%E7%9B%B8%E5%85%B3%E5%8F%82%E8%A7%82%E4%BD%93%E9%AA%8C","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E6%96%87%E6%98%8C%E8%88%AA%E5%A4%A9%E5%8F%91%E5%B0%84%E5%9C%BA%E7%9B%B8%E5%85%B3%E5%8F%82%E8%A7%82%E4%BD%93%E9%AA%8C"},{"id":67,"name":"瑶光火箭观礼平台","enName":"Yaoguang Rocket Viewing Platform","city":"文昌","category":"海南环岛","cn":"文昌市东郊镇X183附近的瑶光火箭观礼平台。它是专门为了看火箭发射而建的观礼平台，不是普通观海台。真正值得来的时候是有发射任务时，可以和大家一起倒数、感受火箭点火升空，座位和道路需要提前预约。","en":"You can find it at Yaoguang Rocket Viewing Platform in Dongjiao Town, along X183, Wenchang. This platform is built for rocket launches, not ordinary sightseeing. On launch day, the countdown and liftoff are the main event. Book ahead and follow road-control instructions.","location":"文昌市东郊镇X183附近的瑶光火箭观礼平台","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E7%91%B6%E5%85%89%E7%81%AB%E7%AE%AD%E8%A7%82%E7%A4%BC%E5%B9%B3%E5%8F%B0","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E7%91%B6%E5%85%89%E7%81%AB%E7%AE%AD%E8%A7%82%E7%A4%BC%E5%B9%B3%E5%8F%B0"},{"id":68,"name":"月亮湾","enName":"Moon Bay","city":"文昌","category":"海南环岛","cn":"文昌市龙楼镇铜鼓岭山脚的月亮湾海岸。从高处看，这片海湾像一条长长的弧线，海水颜色很漂亮。可以结合铜鼓岭一起玩：山上拍全景，来到海边再看沙滩与海浪。","en":"You can find it at Moon Bay below Tongguling in Longlou Town, Wenchang. From above, the shoreline forms a beautiful long curve. Combine it with Tongguling—take wide shots from the hill and then enjoy the beach up close.","location":"文昌市龙楼镇铜鼓岭山脚的月亮湾海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E6%9C%88%E4%BA%AE%E6%B9%BE","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E6%9C%88%E4%BA%AE%E6%B9%BE"},{"id":69,"name":"三婆与海·糟粕醋文化休闲庄园","enName":"Sanpo & Sea Zaopocu Restaurant","city":"文昌","category":"海南环岛","cn":"文昌市铺前镇木兰湾海岸、007乡道附近。这家近年挺火的海边餐厅，纯白建筑放在蓝天大海前面，很像热门旅拍取景地。除了拍照，还能尝文昌有特色的酸辣糟粕醋，属于既能吃又能出片的地方。","en":"It is near County Road 007 on the Mulan Bay coast, Puqian Town, Wenchang. This seaside spot became popular for its white building against the blue sea, almost like a Mediterranean-style photo set. It's also a chance to try Wenchang's tangy, spicy zaopocu specialty.","location":"文昌市铺前镇木兰湾海岸、007乡道附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E4%B8%89%E5%A9%86%E4%B8%8E%E6%B5%B7%C2%B7%E7%B3%9F%E7%B2%95%E9%86%8B%E6%96%87%E5%8C%96%E4%BC%91%E9%97%B2%E5%BA%84%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E4%B8%89%E5%A9%86%E4%B8%8E%E6%B5%B7%C2%B7%E7%B3%9F%E7%B2%95%E9%86%8B%E6%96%87%E5%8C%96%E4%BC%91%E9%97%B2%E5%BA%84%E5%9B%AD"},{"id":70,"name":"铺前老街","enName":"Puqian Old Street","city":"文昌","category":"海南环岛","cn":"文昌市铺前镇老街区，铺前大桥东侧附近。这里的骑楼和海口老街有相似的南洋感觉，不过节奏更像一个安静的海边小镇。可以看老房子、找当地小吃，再把木兰湾一起安排成一趟短途自驾。","en":"You can find it at The old streets of Puqian Town, Wenchang, near the eastern side of Puqian Bridge. The old arcaded buildings have a similar Southeast Asian feel to Haikou, but in a quieter seaside town. Explore the streets, try local snacks, and combine it with Mulan Bay.","location":"文昌市铺前镇老街区，铺前大桥东侧附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E9%93%BA%E5%89%8D%E8%80%81%E8%A1%97","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%96%87%E6%98%8C%E9%93%BA%E5%89%8D%E8%80%81%E8%A1%97"},{"id":71,"name":"潭门渔港","enName":"Tanmen Fishing Harbor","city":"琼海","category":"海南环岛","cn":"琼海市潭门镇潭门渔港。这里的特色是真正的渔港，不是专门摆出来给游客看的布景。能看到出海渔船、渔货交易和海鲜店，喜欢观察本地生活的人会觉得很有意思。","en":"You can find it at Tanmen Fishing Port in Tanmen Town, Qionghai. This is a working fishing port, not a staged tourist village. Watch the boats, see the catch coming in, and enjoy fresh seafood nearby.","location":"琼海市潭门镇潭门渔港","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E6%BD%AD%E9%97%A8%E6%B8%94%E6%B8%AF","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E6%BD%AD%E9%97%A8%E6%B8%94%E6%B8%AF"},{"id":72,"name":"博鳌海的故事","enName":"Boao Story of the Sea","city":"琼海","category":"海南环岛","cn":"琼海市博鳌镇海边的海的故事休闲区。这边最适合不赶时间地看海，餐桌、海边装饰和浪花放在一起很有度假感觉。找个靠海的位置喝饮料、聊聊天，比专程打卡一张照片更有意思。","en":"You can find it at The Story of the Sea waterfront area in Bo'ao Town, Qionghai. This is a relaxed seaside hangout with drinks, coastal décor, and waves close by. Find a good table and enjoy the view without rushing.","location":"琼海市博鳌镇海边的海的故事休闲区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E5%8D%9A%E9%B3%8C%E6%B5%B7%E7%9A%84%E6%95%85%E4%BA%8B","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E5%8D%9A%E9%B3%8C%E6%B5%B7%E7%9A%84%E6%95%85%E4%BA%8B"},{"id":73,"name":"玉带滩","enName":"Jade Belt Beach","city":"琼海","category":"海南环岛","cn":"琼海市博鳌镇万泉河入海口附近。这里最奇特的是长长的沙洲，一边是河水，一边是大海，两种水域在附近相遇。一般需要按景区安排乘船前往，别把它当成随时能自己走上去的普通沙滩。","en":"It is near the mouth of the Wanquan River in Bo'ao Town, Qionghai. This narrow sandbar sits between the river and the sea, making it a very unusual landscape. Access normally follows the scenic area's boat arrangements, so plan ahead.","location":"琼海市博鳌镇万泉河入海口附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E7%8E%89%E5%B8%A6%E6%BB%A9","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E7%8E%89%E5%B8%A6%E6%BB%A9"},{"id":74,"name":"沙美村","enName":"Shamei Village","city":"琼海","category":"海南环岛","cn":"琼海市博鳌镇沙美村，靠近沙美内海。这里的画面很柔和：小村庄、湖面、湿地和远处的山连在一起。适合慢慢走、看看田园和水鸟，和热闹的海滩度假完全是两种感觉。","en":"You can find it at Shamei Village in Bo'ao Town, beside Shamei Lagoon. Shamei is about peaceful countryside scenery—village lanes, wetlands, water, and distant hills. It's a slower and quieter break from crowded beaches.","location":"琼海市博鳌镇沙美村，靠近沙美内海","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E6%B2%99%E7%BE%8E%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E6%B2%99%E7%BE%8E%E6%9D%91"},{"id":75,"name":"世界热带水果之窗","enName":"World Tropical Fruit Window","city":"琼海","category":"海南环岛","cn":"琼海市大路镇世界热带水果之窗景区。这里最有意思的是能认识来自不同地方、平时在超市不常见的热带水果。适合喜欢新鲜水果的人，看看果树长什么样，比只在水果店买水果更有趣。","en":"You can find it at Window to the World of Tropical Fruits in Dalu Town, Qionghai. See tropical fruit growing on trees instead of only on supermarket shelves. It's fun for anyone curious about unusual fruit varieties and where they come from.","location":"琼海市大路镇世界热带水果之窗景区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E4%B8%96%E7%95%8C%E7%83%AD%E5%B8%A6%E6%B0%B4%E6%9E%9C%E4%B9%8B%E7%AA%97","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E4%B8%96%E7%95%8C%E7%83%AD%E5%B8%A6%E6%B0%B4%E6%9E%9C%E4%B9%8B%E7%AA%97"},{"id":76,"name":"白石岭","enName":"Baishiling Mountain","city":"琼海","category":"海南环岛","cn":"琼海市嘉积镇附近白石岭景区。想从平地换个视角看琼海，可以来这座山。登高以后能看到城市、田野和周围山景，适合喜欢爬山又不想跑太远的人。","en":"You can find it at Baishiling Scenic Area near Jiaji Town, Qionghai. Climb above the surrounding fields and town for a different view of Qionghai. It's a good option if you want some elevation without traveling far inland.","location":"琼海市嘉积镇附近白石岭景区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E7%99%BD%E7%9F%B3%E5%B2%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E7%99%BD%E7%9F%B3%E5%B2%AD"},{"id":77,"name":"北仍村","enName":"Beireng Village","city":"琼海","category":"海南环岛","cn":"琼海市嘉积镇北仍村乡村旅游区。这里把乡村绿植、小路和咖啡休闲空间结合起来，感觉比较清静。适合喜欢慢生活、想在海南乡下坐一会儿的人，不是追求刺激项目的景点。","en":"You can find it at Beireng Village near Jiaji Town, Qionghai. This green rural village is more about slow walks and quiet breaks than big attractions. It's nice for seeing the countryside at an easy pace.","location":"琼海市嘉积镇北仍村乡村旅游区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E5%8C%97%E4%BB%8D%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E7%90%BC%E6%B5%B7%E5%8C%97%E4%BB%8D%E6%9D%91"},{"id":78,"name":"日月湾","enName":"Riyue Bay","city":"万宁","category":"海南环岛","cn":"万宁市礼纪镇日月湾，海南东线海岸。这里是海南非常有名的冲浪海湾，浪板、冲浪店和海边咖啡馆随处可见，年轻人特别多。就算不会冲浪，也可以找正规教练上体验课，或者坐着看高手追浪。","en":"You can find it at Riyue Bay in Liji Town, Wanning, on Hainan's east coast. One of Hainan's best-known surf spots, with boards, surf schools, and beach cafés everywhere. Try a beginner lesson with a qualified instructor, or simply watch the surfers.","location":"万宁市礼纪镇日月湾，海南东线海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E6%97%A5%E6%9C%88%E6%B9%BE","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E6%97%A5%E6%9C%88%E6%B9%BE"},{"id":79,"name":"日月湾礼堂","enName":"Riyue Bay Chapel","city":"万宁","category":"海南环岛","cn":"万宁市礼纪镇日月湾海边的日月湾礼堂。这栋海边建筑因为简洁的造型和海景背景很受情侣、摄影博主欢迎。真正吸引人的是建筑线条和海浪同框，适合在冲浪之外顺便拍一组漂亮的照片。","en":"You can find it at The seaside chapel-like building at Riyue Bay in Liji Town, Wanning. This simple seaside building is popular for couple and influencer photos. Its clean lines against the waves make a lovely shot while you're visiting the surf bay.","location":"万宁市礼纪镇日月湾海边的日月湾礼堂","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E6%97%A5%E6%9C%88%E6%B9%BE%E7%A4%BC%E5%A0%82","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E6%97%A5%E6%9C%88%E6%B9%BE%E7%A4%BC%E5%A0%82"},{"id":80,"name":"石梅湾","enName":"Shimei Bay","city":"万宁","category":"海南环岛","cn":"万宁市礼纪镇石梅湾海岸。这里和热闹的日月湾不同，海滩、椰林和度假酒店带来更安静的度假感觉。适合找个地方住一晚、早晨走沙滩，而不只是来拍照五分钟就走。","en":"You can find it at Shimei Bay in Liji Town, Wanning. Quieter than the surf scene at Riyue Bay, Shimei Bay is about palm-lined beaches and relaxed resorts. It's a place to stay, slow down, and walk on the sand in the morning.","location":"万宁市礼纪镇石梅湾海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E7%9F%B3%E6%A2%85%E6%B9%BE","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E7%9F%B3%E6%A2%85%E6%B9%BE"},{"id":81,"name":"神州半岛","enName":"Shenzhou Peninsula","city":"万宁","category":"海南环岛","cn":"万宁市东澳镇神州半岛海岸。半岛两侧都有海景，路边常能看到漂亮的海湾和度假建筑。适合自驾、住海边酒店，顺便把灯塔放进当天的拍照路线。","en":"You can find it at Shenzhou Peninsula in Dong'ao Town, Wanning. This peninsula gives you coastal views from different angles, with beaches and resorts along the way. Combine a scenic drive with a visit to its lighthouse.","location":"万宁市东澳镇神州半岛海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E7%A5%9E%E5%B7%9E%E5%8D%8A%E5%B2%9B","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E7%A5%9E%E5%B7%9E%E5%8D%8A%E5%B2%9B"},{"id":82,"name":"神州半岛灯塔","enName":"Shenzhou Peninsula Lighthouse","city":"万宁","category":"海南环岛","cn":"万宁市东澳镇神州半岛海岸尽头附近的灯塔。这座红白相间的灯塔立在伸入海中的防波堤尽头，非常醒目。海水、堤岸和灯塔一起拍很有画面感，但要看清通行安排，不要冒险走到被封闭的区域。","en":"You can find it at The lighthouse near the end of Shenzhou Peninsula in Dong'ao Town. The red-and-white striped lighthouse stands at the end of a breakwater reaching into the sea. It makes a striking photo with the blue water, but follow access signs and stay away from closed areas.","location":"万宁市东澳镇神州半岛海岸尽头附近的灯塔","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E7%A5%9E%E5%B7%9E%E5%8D%8A%E5%B2%9B%E7%81%AF%E5%A1%94","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E7%A5%9E%E5%B7%9E%E5%8D%8A%E5%B2%9B%E7%81%AF%E5%A1%94"},{"id":83,"name":"兴隆热带植物园","enName":"Xinglong Tropical Botanical Garden","city":"万宁","category":"海南环岛","cn":"万宁市兴隆华侨旅游经济区兴隆热带植物园。这里有很多平时很少见的香料和热带经济植物，咖啡、可可也能看到真实植物。适合对食物来源好奇的人，不是只有走马观花看花草。","en":"You can find it at Xinglong Tropical Botanical Garden in Wanning's Xinglong Overseas Chinese area. See where coffee, cocoa, spices, and other tropical crops actually come from. It's especially interesting if you enjoy food and want to learn about the plants behind it.","location":"万宁市兴隆华侨旅游经济区兴隆热带植物园","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E5%85%B4%E9%9A%86%E7%83%AD%E5%B8%A6%E6%A4%8D%E7%89%A9%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E5%85%B4%E9%9A%86%E7%83%AD%E5%B8%A6%E6%A4%8D%E7%89%A9%E5%9B%AD"},{"id":84,"name":"兴隆咖啡文化街区","enName":"Xinglong Coffee Area","city":"万宁","category":"海南环岛","cn":"万宁市兴隆华侨旅游经济区的兴隆咖啡街区。兴隆的咖啡文化和归侨历史联系很深，很多人会专程来喝当地咖啡、尝南洋风味点心。这里不是只拍一张咖啡杯，而是能体验海南很有地方特色的咖啡生活。","en":"You can find it at Coffee spots around Xinglong in Wanning's Overseas Chinese area. Xinglong has a strong coffee tradition shaped by overseas Chinese communities. Come for local coffee and Southeast Asian-influenced snacks, not just another café photo.","location":"万宁市兴隆华侨旅游经济区的兴隆咖啡街区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E5%85%B4%E9%9A%86%E5%92%96%E5%95%A1%E6%96%87%E5%8C%96%E8%A1%97%E5%8C%BA","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E5%85%B4%E9%9A%86%E5%92%96%E5%95%A1%E6%96%87%E5%8C%96%E8%A1%97%E5%8C%BA"},{"id":85,"name":"巴厘村","enName":"Bali Village","city":"万宁","category":"海南环岛","cn":"万宁市兴隆华侨旅游经济区巴厘村景区。这里有不少东南亚风格建筑和装饰，能看出归侨文化对兴隆的影响。适合想拍异域风情照片、又想知道海南为什么有这么多南洋元素的人。","en":"You can find it at Bali Village in the Xinglong area of Wanning. The Southeast Asian-style buildings reflect Xinglong's overseas Chinese heritage. It's a photogenic stop and a good way to see how regional cultures mix in Hainan.","location":"万宁市兴隆华侨旅游经济区巴厘村景区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E5%B7%B4%E5%8E%98%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E5%B7%B4%E5%8E%98%E6%9D%91"},{"id":86,"name":"山钦湾燕子洞海岸","enName":"Shanqin Bay Sea Cave Coast","city":"万宁","category":"海南环岛","cn":"万宁市山钦湾海岸，燕子洞一带。这里最抢眼的是海蚀洞和黑色岩石，海浪拍上来时画面很壮观。它是自然海岸，不是设施完善的沙滩景区，潮汐和浪况危险，建议只在安全位置远观。","en":"You can find it at The rocky Yanzi Cave coastline at Shanqin Bay, Wanning. The sea cave and dark rocks look dramatic when waves crash in. This is a wild coastline, not a developed beach, so stay well away from dangerous surf and slippery cliffs.","location":"万宁市山钦湾海岸，燕子洞一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E5%B1%B1%E9%92%A6%E6%B9%BE%E7%87%95%E5%AD%90%E6%B4%9E%E6%B5%B7%E5%B2%B8","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E5%B1%B1%E9%92%A6%E6%B9%BE%E7%87%95%E5%AD%90%E6%B4%9E%E6%B5%B7%E5%B2%B8"},{"id":87,"name":"大花角","enName":"Dahuajiao Coast","city":"万宁","category":"海南环岛","cn":"万宁市东澳镇大花角海岸。这里的石头和自然海岸是亮点，没有太多商业设施，更有荒野感。适合喜欢礁石、海浪和海岸摄影的人，注意路况、海浪和不要攀爬危险岩石。","en":"You can find it at Dahuajiao coast in Dong'ao Town, Wanning. This stretch is about rugged rocks and an undeveloped coastline rather than cafés. It's great for dramatic scenery, but access and surf conditions need care.","location":"万宁市东澳镇大花角海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E5%A4%A7%E8%8A%B1%E8%A7%92","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%87%E5%AE%81%E5%A4%A7%E8%8A%B1%E8%A7%92"},{"id":88,"name":"分界洲岛","enName":"Boundary Island","city":"陵水","category":"海南环岛","cn":"陵水黎族自治县牛岭附近的分界洲岛景区。这座岛的海水通常很通透，水上活动和潜水是主要卖点。可以坐船上岛，在正规运营区域体验海洋项目；风浪太大时出海可能调整。","en":"You can find it at Fenjiezhou Island off the coast near Niuling in Lingshui. The island is known for clear-looking water and marine activities, especially diving. Take the official boat and use licensed operators; trips can change with the weather.","location":"陵水黎族自治县牛岭附近的分界洲岛景区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E5%88%86%E7%95%8C%E6%B4%B2%E5%B2%9B","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E5%88%86%E7%95%8C%E6%B4%B2%E5%B2%9B"},{"id":89,"name":"南湾猴岛","enName":"Nanwan Monkey Island","city":"陵水","category":"海南环岛","cn":"陵水黎族自治县新村镇南湾猴岛。这里可以近距离观察猕猴，坐缆车时还能俯瞰渔排和海湾，画面很有海南特色。猴子毕竟是野生动物，别拿食物逗弄或靠太近。","en":"You can find it at Nanwan Monkey Island in Xincun Town, Lingshui. You can see macaques and ride a cable car above the fishing rafts and bay. The monkeys are wild animals, so keep your distance and don't tease them with food.","location":"陵水黎族自治县新村镇南湾猴岛","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E5%8D%97%E6%B9%BE%E7%8C%B4%E5%B2%9B","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E5%8D%97%E6%B9%BE%E7%8C%B4%E5%B2%9B"},{"id":90,"name":"呆呆岛","enName":"Daida Island","city":"陵水","category":"海南环岛","cn":"陵水黎族自治县新村镇南湾一带的呆呆岛。这里的海滩比较适合拍清新、度假风格的照片，很多人冲着椰树、沙滩和海边小布景来。更适合慢慢玩半天，不需要把它当成刺激冒险地点。","en":"You can find it at Daidai Island in the Nanwan area near Xincun Town, Lingshui. A relaxed beach area popular for holiday-style photos, palms, and seaside scenery. It's better for a gentle half-day than for action-packed adventure.","location":"陵水黎族自治县新村镇南湾一带的呆呆岛","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E5%91%86%E5%91%86%E5%B2%9B","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E5%91%86%E5%91%86%E5%B2%9B"},{"id":91,"name":"清水湾","enName":"Clearwater Bay","city":"陵水","category":"海南环岛","cn":"陵水黎族自治县英州镇清水湾海岸。这里的沙滩很长、海面宽阔，看起来很有高级海滨度假区的感觉。适合在海边走很长一段路、住海景酒店，享受不用赶景点的度假节奏。","en":"You can find it at Clearwater Bay in Yingzhou Town, Lingshui. This long, wide beach has a polished resort feel. It's ideal for an extended seaside walk, a hotel stay, and a slower holiday pace.","location":"陵水黎族自治县英州镇清水湾海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E6%B8%85%E6%B0%B4%E6%B9%BE","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E6%B8%85%E6%B0%B4%E6%B9%BE"},{"id":92,"name":"新村港疍家渔排","enName":"Xincun Harbor Floating Fishing Village","city":"陵水","category":"海南环岛","cn":"陵水黎族自治县新村镇新村港渔排区。这里最有特色的是渔民把生活和养殖场所建在水上，一排排渔排看起来很特别。可以体验疍家水上生活、吃海鲜，但乘船要选正规、安全的运营者。","en":"You can find it at The floating fishing rafts at Xincun Harbor, Lingshui. The floating fish farms and homes create a remarkable waterside scene. It's a chance to learn about Danjia fishing life and enjoy seafood, using safe, approved boats.","location":"陵水黎族自治县新村镇新村港渔排区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E6%96%B0%E6%9D%91%E6%B8%AF%E7%96%8D%E5%AE%B6%E6%B8%94%E6%8E%92","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E6%96%B0%E6%9D%91%E6%B8%AF%E7%96%8D%E5%AE%B6%E6%B8%94%E6%8E%92"},{"id":93,"name":"香水湾","enName":"Xiangshui Bay","city":"陵水","category":"海南环岛","cn":"陵水黎族自治县香水湾海岸。这里的海滩相对安静，海景开阔，适合想避开热门景区人群的人。比较适合安排酒店度假、散步或拍风景，而不是期待一整条商业街。","en":"You can find it at Xiangshui Bay on the coast of Lingshui. Quieter than the most famous beach resorts, this bay is better for peaceful sea views and long walks. Come for a relaxed stay rather than busy nightlife.","location":"陵水黎族自治县香水湾海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E9%A6%99%E6%B0%B4%E6%B9%BE","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E9%A6%99%E6%B0%B4%E6%B9%BE"},{"id":94,"name":"富力湾","enName":"Fuli Bay","city":"陵水","category":"海南环岛","cn":"陵水黎族自治县富力湾海岸。富力湾的看点主要是海边度假环境和宽阔的岸线，比较适合放松。它不是非来不可的独特地标，更适合住在附近时顺路看看海。","en":"You can find it at Fuli Bay on the coast of Lingshui. This is mainly a relaxed resort coastline with broad sea views. It's a good nearby stop if you're staying in the area, rather than a must-see landmark.","location":"陵水黎族自治县富力湾海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E5%AF%8C%E5%8A%9B%E6%B9%BE","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E9%99%B5%E6%B0%B4%E5%AF%8C%E5%8A%9B%E6%B9%BE"},{"id":95,"name":"天涯小镇","enName":"Tianya Town","city":"三亚","category":"海南环岛","cn":"三亚市天涯区天涯小镇，靠近三亚湾西侧海岸。这里因为蓝白配色的巷子和海边咖啡馆很火，很多人穿浅色衣服来拍照。巷子走到底就能看到大海，拍街景和拍海景可以在同一趟完成。","en":"You can find it at Tianya Town in Tianya District, by the western end of Sanya Bay. The blue-and-white lanes and seaside cafés have made this a popular photo town. Wear light colors if you like the style, and walk through the lanes until they open toward the sea.","location":"三亚市天涯区天涯小镇，靠近三亚湾西侧海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E5%A4%A9%E6%B6%AF%E5%B0%8F%E9%95%87","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E5%A4%A9%E6%B6%AF%E5%B0%8F%E9%95%87"},{"id":96,"name":"后海村","enName":"Houhai Village","city":"三亚","category":"海南环岛","cn":"三亚市海棠区后海村，蜈支洲岛码头附近。后海的氛围和高级度假酒店很不一样，冲浪学校、海边小店和年轻人特别多。白天可以学冲浪，晚上再去海边找个小酒吧坐坐。","en":"You can find it at Houhai Village in Haitang District, near the Wuzhizhou Island pier. Houhai feels youthful and casual, with surf schools, beach cafés, and bars. Take a surf lesson during the day, then stay for the easygoing evening scene.","location":"三亚市海棠区后海村，蜈支洲岛码头附近","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E5%90%8E%E6%B5%B7%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E5%90%8E%E6%B5%B7%E6%9D%91"},{"id":97,"name":"西岛","enName":"West Island","city":"三亚","category":"海南环岛","cn":"三亚市天涯区西岛景区，乘船从码头上岛。这里不只是一个海岛景区，岛上还有真正的渔村、街巷和居民生活。可以租车或步行逛村子、尝海鲜，慢慢感受岛上的生活节奏。","en":"You can find it at West Island off Tianya District, reached by ferry. West Island is more than a beach stop—it has a real fishing village with lanes and daily island life. Explore on foot, try seafood, and take your time.","location":"三亚市天涯区西岛景区，乘船从码头上岛","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E8%A5%BF%E5%B2%9B","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E8%A5%BF%E5%B2%9B"},{"id":98,"name":"蜈支洲岛","enName":"Wuzhizhou Island","city":"三亚","category":"海南环岛","cn":"三亚市海棠区蜈支洲岛，后海一带码头乘船。这座岛很适合想玩水上项目的人，尤其是潜水和海洋娱乐。海水颜色、沙滩和热带植物都很漂亮，但船班和项目受天气影响。","en":"You can find it at Wuzhizhou Island off Haitang District, reached by boat near Houhai. This is one of Sanya's best-known islands for diving and water activities. The water and beaches are beautiful, but boats and activities depend on sea conditions.","location":"三亚市海棠区蜈支洲岛，后海一带码头乘船","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E8%9C%88%E6%94%AF%E6%B4%B2%E5%B2%9B","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E8%9C%88%E6%94%AF%E6%B4%B2%E5%B2%9B"},{"id":99,"name":"亚龙湾","enName":"Yalong Bay","city":"三亚","category":"海南环岛","cn":"三亚市吉阳区亚龙湾海岸。亚龙湾是三亚经典的度假海湾，沙滩细，海边酒店也很多。最适合在这边住一两晚，白天玩沙滩、傍晚看海，而不是只来拍一张照片。","en":"You can find it at Yalong Bay in Jiyang District, Sanya. Yalong Bay is a classic Sanya resort beach with fine sand and many hotels. It's best enjoyed as a relaxed stay rather than a quick photo stop.","location":"三亚市吉阳区亚龙湾海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E4%BA%9A%E9%BE%99%E6%B9%BE","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E4%BA%9A%E9%BE%99%E6%B9%BE"},{"id":100,"name":"大东海","enName":"Dadonghai Beach","city":"三亚","category":"海南环岛","cn":"三亚市吉阳区大东海旅游区。这里比一些安静海湾更热闹，海边有不少餐厅、酒吧和游客活动。适合喜欢交通方便、下楼就能吃喝逛海滩的人。","en":"You can find it at Dadonghai Beach in Jiyang District, Sanya. Dadonghai has more of a lively beach-town feeling, with restaurants and entertainment close to the shore. It's convenient if you like everything within walking distance.","location":"三亚市吉阳区大东海旅游区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E5%A4%A7%E4%B8%9C%E6%B5%B7","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E5%A4%A7%E4%B8%9C%E6%B5%B7"},{"id":101,"name":"椰梦长廊","enName":"Coconut Dream Corridor","city":"三亚","category":"海南环岛","cn":"三亚市天涯区三亚湾路沿线的椰梦长廊。最适合来的时间是傍晚：夕阳慢慢落到海面上，椰树变成剪影，非常适合拍人像。这里也是市民和游客一起散步、跳舞、看日落的地方。","en":"You can find it at The palm-lined coastal stretch along Sanya Bay Road, Tianya District. Sunset is the magic moment, when palm trees become silhouettes against the sea. Locals and visitors gather here to walk, dance, and take portraits in the golden light.","location":"三亚市天涯区三亚湾路沿线的椰梦长廊","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E6%A4%B0%E6%A2%A6%E9%95%BF%E5%BB%8A","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E6%A4%B0%E6%A2%A6%E9%95%BF%E5%BB%8A"},{"id":102,"name":"鹿回头风景区","enName":"Luhuitou Scenic Park","city":"三亚","category":"海南环岛","cn":"三亚市吉阳区鹿回头风景区。这里不是普通海滩，而是能从山上俯瞰整个三亚湾和城市高楼。尤其晚上灯亮起来以后，可以拍到很漂亮的三亚夜景。","en":"You can find it at Luhuitou Scenic Area in Jiyang District, Sanya. Come here for an elevated view of Sanya's bays and skyline rather than the beach itself. After dark, the city lights make a beautiful panorama.","location":"三亚市吉阳区鹿回头风景区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E9%B9%BF%E5%9B%9E%E5%A4%B4%E9%A3%8E%E6%99%AF%E5%8C%BA","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E9%B9%BF%E5%9B%9E%E5%A4%B4%E9%A3%8E%E6%99%AF%E5%8C%BA"},{"id":103,"name":"亚龙湾热带天堂森林公园","enName":"Yalong Bay Tropical Paradise Forest Park","city":"三亚","category":"海南环岛","cn":"三亚市吉阳区亚龙湾热带天堂森林公园。这个景区能同时看热带树林和远处的亚龙湾，站在高处拍出来特别有层次。适合喜欢山海同框、又不想整天只待在沙滩的人。","en":"You can find it at Yalong Bay Tropical Paradise Forest Park in Jiyang District. This park combines lush tropical hills with distant views of Yalong Bay. It's great for layered mountain-and-sea photos and a change from beach time.","location":"三亚市吉阳区亚龙湾热带天堂森林公园","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E4%BA%9A%E9%BE%99%E6%B9%BE%E7%83%AD%E5%B8%A6%E5%A4%A9%E5%A0%82%E6%A3%AE%E6%9E%97%E5%85%AC%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E4%BA%9A%E9%BE%99%E6%B9%BE%E7%83%AD%E5%B8%A6%E5%A4%A9%E5%A0%82%E6%A3%AE%E6%9E%97%E5%85%AC%E5%9B%AD"},{"id":104,"name":"梅联社区海边渔村","enName":"Meilian Coastal Art Village","city":"三亚","category":"海南环岛","cn":"三亚市崖州区梅联社区，靠近乐东龙栖湾。这里原本是海边渔村，现在有蓝色海洋主题墙绘和有创意的街角装置。比热门打卡小镇安静，适合拍村落生活和海边艺术感的照片。","en":"You can find it at Meilian Community in Yazhou District, near Ledong's Longqi Bay. This former fishing village now has blue ocean-themed murals and small creative installations. It's quieter than the big photo towns, with an appealing mix of village life and art.","location":"三亚市崖州区梅联社区，靠近乐东龙栖湾","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E6%A2%85%E8%81%94%E7%A4%BE%E5%8C%BA%E6%B5%B7%E8%BE%B9%E6%B8%94%E6%9D%91","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E6%A2%85%E8%81%94%E7%A4%BE%E5%8C%BA%E6%B5%B7%E8%BE%B9%E6%B8%94%E6%9D%91"},{"id":105,"name":"三亚国际免税城","enName":"Sanya International Duty Free Mall","city":"三亚","category":"海南环岛","cn":"三亚市海棠区海棠北路的三亚国际免税城。这是三亚大型免税购物地，适合买化妆品、国际品牌和伴手礼。它主要是购物体验，不必把它和海湾、雨林这类自然景点放在同一优先级。","en":"You can find it at Sanya International Duty Free Shopping Complex on Haitang North Road, Haitang District. This huge duty-free complex is for international brands, cosmetics, and gifts. It's a shopping stop rather than a natural attraction.","location":"三亚市海棠区海棠北路的三亚国际免税城","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E4%B8%89%E4%BA%9A%E5%9B%BD%E9%99%85%E5%85%8D%E7%A8%8E%E5%9F%8E","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E4%B8%89%E4%BA%9A%E5%9B%BD%E9%99%85%E5%85%8D%E7%A8%8E%E5%9F%8E"},{"id":106,"name":"亚特兰蒂斯水世界","enName":"Atlantis Aquaventure Waterpark","city":"三亚","category":"海南环岛","cn":"三亚市海棠区亚特兰蒂斯度假区内。如果喜欢刺激水上滑道，这里比普通海滩更适合。水世界有多种不同强度的项目，适合和朋友玩一整天，但门票、开放区域要提前确认。","en":"It is inside Atlantis Resort in Haitang District, Sanya. If you love water slides, this is more exciting than a normal beach day. There are attractions with different thrill levels, so check tickets and operating areas ahead of time.","location":"三亚市海棠区亚特兰蒂斯度假区内","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E4%BA%9A%E7%89%B9%E5%85%B0%E8%92%82%E6%96%AF%E6%B0%B4%E4%B8%96%E7%95%8C","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E4%BA%9A%E7%89%B9%E5%85%B0%E8%92%82%E6%96%AF%E6%B0%B4%E4%B8%96%E7%95%8C"},{"id":107,"name":"太阳湾公路沿线观景区","enName":"Sun Bay Coastal Road","city":"三亚","category":"海南环岛","cn":"三亚市吉阳区太阳湾公路沿线的合法观景位置。这一带最漂亮的是沿着山坡蜿蜒的海岸公路，转弯处常能看到层层蓝色的海。拍照要在安全且允许停靠的位置，不能站到车道中间取景。","en":"You can find it at Officially accessible viewpoints along Sun Bay Road in Jiyang District. The winding coastal road gives you beautiful layers of blue sea below the hills. Only stop where permitted and never stand in the road for a photo.","location":"三亚市吉阳区太阳湾公路沿线的合法观景位置","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E5%A4%AA%E9%98%B3%E6%B9%BE%E5%85%AC%E8%B7%AF%E6%B2%BF%E7%BA%BF%E8%A7%82%E6%99%AF%E5%8C%BA","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%89%E4%BA%9A%E5%A4%AA%E9%98%B3%E6%B9%BE%E5%85%AC%E8%B7%AF%E6%B2%BF%E7%BA%BF%E8%A7%82%E6%99%AF%E5%8C%BA"},{"id":108,"name":"保亭呀诺达雨林文化旅游区","enName":"Yanoda Rainforest Cultural Tourism Zone","city":"其他地区","category":"海南环岛","cn":"保亭黎族苗族自治县三道镇呀诺达景区。这里最大的特色是热带雨林的湿润感：大叶植物、溪流、山谷和雨林步道都很有海南中部的味道。适合想离开海滩，到真正热带森林里走一走的人。","en":"You can find it at Yanoda Rainforest Scenic Area in Sandao Town, Baoting. Step away from the beach into lush rainforest, streams, and valley trails. The dense greenery and humid forest air make it feel like a different part of Hainan.","location":"保亭黎族苗族自治县三道镇呀诺达景区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%BF%9D%E4%BA%AD%E5%91%80%E8%AF%BA%E8%BE%BE%E9%9B%A8%E6%9E%97%E6%96%87%E5%8C%96%E6%97%85%E6%B8%B8%E5%8C%BA","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%BF%9D%E4%BA%AD%E5%91%80%E8%AF%BA%E8%BE%BE%E9%9B%A8%E6%9E%97%E6%96%87%E5%8C%96%E6%97%85%E6%B8%B8%E5%8C%BA"},{"id":109,"name":"保亭槟榔谷","enName":"Binglanggu Li & Miao Cultural Park","city":"其他地区","category":"海南环岛","cn":"保亭黎族苗族自治县三道镇槟榔谷景区。这里比较有意思的是能看到海南黎族传统织锦、服饰和民俗技艺，不只是看一场表演。想让外国朋友了解海南本地少数民族文化，这里比较直观。","en":"You can find it at Binglanggu Scenic Area in Sandao Town, Baoting. This is a good place to learn about Hainan's Li culture, including traditional textiles, clothing, and crafts. There's more to see than just staged performances.","location":"保亭黎族苗族自治县三道镇槟榔谷景区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%BF%9D%E4%BA%AD%E6%A7%9F%E6%A6%94%E8%B0%B7","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%BF%9D%E4%BA%AD%E6%A7%9F%E6%A6%94%E8%B0%B7"},{"id":110,"name":"保亭七仙岭","enName":"Qixianling Hot Springs","city":"其他地区","category":"海南环岛","cn":"保亭黎族苗族自治县七仙岭温泉国家森林公园一带。这里是雨林山景和温泉结合的度假路线，天气稍凉时泡温泉特别舒服。适合想休息、住一晚山林度假酒店的人。","en":"You can find it at Qixianling Hot Spring Forest Park in Baoting. The appeal here is the combination of green forested hills and hot springs. It's best for a restful overnight escape rather than a packed sightseeing day.","location":"保亭黎族苗族自治县七仙岭温泉国家森林公园一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%BF%9D%E4%BA%AD%E4%B8%83%E4%BB%99%E5%B2%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%BF%9D%E4%BA%AD%E4%B8%83%E4%BB%99%E5%B2%AD"},{"id":111,"name":"五指山热带雨林","enName":"Wuzhishan Tropical Rainforest","city":"其他地区","category":"海南环岛","cn":"五指山市水满乡五指山热带雨林一带。这里是海南中部的山地雨林，植被、气温和海边差别明显。喜欢自然的人可以走开放步道、看看雾气和山谷，不建议擅自进入未开放的原始林区。","en":"It is around Shuiman Township in Wuzhishan City, in Hainan's central highlands. The central mountains feel very different from the coast, with dense forest and cooler, misty scenery. Stick to designated trails and don't enter restricted forest areas.","location":"五指山市水满乡五指山热带雨林一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%BA%94%E6%8C%87%E5%B1%B1%E7%83%AD%E5%B8%A6%E9%9B%A8%E6%9E%97","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%BA%94%E6%8C%87%E5%B1%B1%E7%83%AD%E5%B8%A6%E9%9B%A8%E6%9E%97"},{"id":112,"name":"乐东尖峰岭国家森林公园","enName":"Jianfengling National Forest Park","city":"其他地区","category":"海南环岛","cn":"乐东黎族自治县尖峰镇尖峰岭国家森林公园。这里有山地雨林、湖泊和森林景观，很适合喜欢徒步和清晨看云雾的人。路程比普通海滨景区远，建议提前计划交通和天气。","en":"You can find it at Jianfengling National Forest Park in Jianfeng Town, Ledong. This forest park offers mountain rainforest, a lake, and misty early-morning scenery. It's for nature lovers who don't mind planning a longer journey.","location":"乐东黎族自治县尖峰镇尖峰岭国家森林公园","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B9%90%E4%B8%9C%E5%B0%96%E5%B3%B0%E5%B2%AD%E5%9B%BD%E5%AE%B6%E6%A3%AE%E6%9E%97%E5%85%AC%E5%9B%AD","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B9%90%E4%B8%9C%E5%B0%96%E5%B3%B0%E5%B2%AD%E5%9B%BD%E5%AE%B6%E6%A3%AE%E6%9E%97%E5%85%AC%E5%9B%AD"},{"id":113,"name":"昌江棋子湾","enName":"Qizi Bay","city":"其他地区","category":"海南环岛","cn":"昌江黎族自治县昌化镇附近棋子湾海岸。这里的海滩、礁石和日落组合很漂亮，海南西线的海景和东线度假区有不一样的荒野感。特别适合喜欢拍夕阳和大片海岸的人。","en":"You can find it at Qizi Bay near Changhua Town, Changjiang County. The mix of rocky coast, open beach, and sunset is beautiful here. Hainan's west coast feels wilder and less resort-like than many eastern beaches.","location":"昌江黎族自治县昌化镇附近棋子湾海岸","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%98%8C%E6%B1%9F%E6%A3%8B%E5%AD%90%E6%B9%BE","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E6%98%8C%E6%B1%9F%E6%A3%8B%E5%AD%90%E6%B9%BE"},{"id":114,"name":"东方鱼鳞洲","enName":"Yulinzhou Coastal Park","city":"其他地区","category":"海南环岛","cn":"东方市八所镇鱼鳞洲风景区。这里有灯塔、风车和礁石海岸，海边拍出来很有辨识度。东方位于海南西海岸，傍晚日落方向特别适合安排海景照片。","en":"You can find it at Yulinzhou Scenic Area in Basuo Town, Dongfang City. A lighthouse, wind turbines, and rocky shoreline make this a distinctive west-coast photo stop. The sunset is the main attraction in the late afternoon.","location":"东方市八所镇鱼鳞洲风景区","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%9C%E6%96%B9%E9%B1%BC%E9%B3%9E%E6%B4%B2","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E4%B8%9C%E6%96%B9%E9%B1%BC%E9%B3%9E%E6%B4%B2"},{"id":115,"name":"儋州峨蔓火山海岸","enName":"Eman Volcanic Coast","city":"其他地区","category":"海南环岛","cn":"儋州市峨蔓镇峨蔓火山海岸一带。这一带的海岸有黑色火山岩和奇形怪状的岩石，跟三亚白沙滩完全是两种画面。适合喜欢野生海岸地貌的人，但部分路段较偏，要注意安全和通行条件。","en":"You can find it at The volcanic coast around Eman Town in Danzhou. Black volcanic rock creates a dramatic coast very different from Sanya's sandy beaches. It's fascinating for geology and landscape photos, but check access and stay clear of unsafe rocks and surf.","location":"儋州市峨蔓镇峨蔓火山海岸一带","mapAmap":"https://uri.amap.com/search?keyword=%E6%B5%B7%E5%8D%97%E7%9C%81%E5%84%8B%E5%B7%9E%E5%B3%A8%E8%94%93%E7%81%AB%E5%B1%B1%E6%B5%B7%E5%B2%B8","mapGoogle":"https://www.google.com/maps/search/?api=1&query=%E6%B5%B7%E5%8D%97%E7%9C%81%E5%84%8B%E5%B7%9E%E5%B3%A8%E8%94%93%E7%81%AB%E5%B1%B1%E6%B5%B7%E5%B2%B8"}]};
